<div class="container-fluid px-4 py-4">

  <div class="alert alert-success alert-dismissible py-2" *ngIf="successMsg">
    <i class="bi bi-check-circle me-1"></i>{{ successMsg }}
    <button type="button" class="btn-close py-2" (click)="successMsg=''"></button>
  </div>
  <div class="alert alert-danger alert-dismissible py-2" *ngIf="error">
    <i class="bi bi-exclamation-circle me-1"></i>{{ error }}
    <button type="button" class="btn-close py-2" (click)="error=''"></button>
  </div>

  <div class="card">
    <div class="card-header d-flex justify-content-between align-items-center">
      <h5 class="mb-0 fw-bold" style="color:#1e40af;">
        <i class="bi bi-building-fill me-2"></i>Entidades / Empresas
      </h5>
      <button class="btn btn-primary btn-sm" (click)="openCreate()">
        <i class="bi bi-plus-lg me-1"></i>Nueva Entidad
      </button>
    </div>

    <div class="text-center py-5" *ngIf="loading">
      <div class="spinner-border text-primary" role="status"></div>
    </div>

    <div class="table-responsive" *ngIf="!loading">
      <table class="table table-hover mb-0">
        <thead>
          <tr>
            <th>#</th>
            <th>Nombre</th>
            <th>Estado</th>
            <th>Correos de notificación</th>
            <th>Vencimiento soporte</th>
            <th>Áreas</th>
            <th class="text-center">Acciones</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let e of entidades">
            <td class="text-muted fw-bold">{{ e.id }}</td>
            <td class="fw-semibold">{{ e.nombre }}</td>
            <td>
              <span class="badge bg-success" *ngIf="e.estado">Activa</span>
              <span class="badge bg-secondary" *ngIf="!e.estado">Inactiva</span>
            </td>
            <td>
              <span *ngIf="!e.correosNotificacion?.length" class="text-muted small">—</span>
              <div class="d-flex flex-wrap gap-1" *ngIf="e.correosNotificacion?.length">
                <span class="badge bg-light text-dark border small"
                  *ngFor="let c of e.correosNotificacion">{{ c }}</span>
              </div>
            </td>
            <td class="small">
              <span *ngIf="!e.fechaVencimientoSoporte" class="text-muted">Sin fecha</span>
              <span *ngIf="e.fechaVencimientoSoporte"
                [class.text-danger]="estaVencido(e.fechaVencimientoSoporte)"
                [class.fw-bold]="estaVencido(e.fechaVencimientoSoporte)">
                <i class="bi bi-calendar-event me-1"></i>
                {{ e.fechaVencimientoSoporte | date:'dd/MM/yyyy' }}
                <span class="badge bg-danger ms-1" *ngIf="estaVencido(e.fechaVencimientoSoporte)">Vencido</span>
              </span>
            </td>
            <td class="small">
              <span class="badge bg-primary rounded-pill">{{ e.areas?.length ?? 0 }}</span>
            </td>
            <td class="text-center" style="white-space:nowrap">
              <button class="btn btn-outline-secondary btn-sm me-1" title="Editar" (click)="openEdit(e)">
                <i class="bi bi-pencil"></i>
              </button>
              <button class="btn btn-sm me-1"
                [class.btn-outline-success]="!e.estado"
                [class.btn-outline-warning]="e.estado"
                [title]="e.estado ? 'Desactivar' : 'Activar'"
                (click)="toggleEstado(e)">
                <i class="bi" [class.bi-toggle-on]="e.estado" [class.bi-toggle-off]="!e.estado"></i>
              </button>
              <button class="btn btn-outline-danger btn-sm" title="Eliminar" (click)="eliminar(e)">
                <i class="bi bi-trash"></i>
              </button>
            </td>
          </tr>
          <tr *ngIf="!entidades.length">
            <td colspan="7" class="text-center text-muted py-4">No hay entidades registradas</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<!-- ══ MODAL: Crear Entidad ══════════════════════════════════════════════════ -->
<div class="modal fade" id="createModal" tabindex="-1">
  <div class="modal-dialog modal-lg">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-building-add me-2"></i>Nueva Entidad</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="createForm">
          <div class="row g-3">
            <div class="col-12">
              <label class="form-label fw-semibold">Nombre de la entidad / empresa <span class="text-danger">*</span></label>
              <input type="text" class="form-control" formControlName="nombre"
                placeholder="Ej: Gobernación del Putumayo" />
              <div class="text-danger small mt-1"
                *ngIf="createForm.get('nombre')?.touched && createForm.get('nombre')?.invalid">
                Mínimo 3 caracteres
              </div>
            </div>

            <div class="col-md-6">
              <label class="form-label fw-semibold">Fecha de vencimiento de soporte</label>
              <input type="date" class="form-control" formControlName="fechaVencimientoSoporte" />
              <div class="form-text">Opcional. Se marcará como vencida si supera esta fecha.</div>
            </div>

            <div class="col-12">
              <label class="form-label fw-semibold">Correos de notificación</label>
              <div class="input-group mb-2">
                <input type="email" class="form-control"
                  [(ngModel)]="nuevoCorreoCreate" [ngModelOptions]="{standalone: true}"
                  placeholder="correo@ejemplo.com"
                  (keyup.enter)="agregarCorreoCreate()" />
                <button class="btn btn-outline-primary" type="button" (click)="agregarCorreoCreate()">
                  <i class="bi bi-plus-lg"></i> Agregar
                </button>
              </div>
              <div class="d-flex flex-wrap gap-2 mt-1">
                <span class="badge bg-primary d-flex align-items-center gap-1 py-2 px-2"
                  style="font-size:0.8rem"
                  *ngFor="let c of correosCreate; let i = index">
                  <i class="bi bi-envelope me-1"></i>{{ c }}
                  <button type="button" class="btn-close btn-close-white ms-1"
                    style="font-size:0.55rem" (click)="quitarCorreoCreate(i)"></button>
                </span>
                <span class="text-muted small fst-italic" *ngIf="!correosCreate.length">
                  Sin correos agregados
                </span>
              </div>
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarEntidad()" [disabled]="saving">
          <span *ngIf="saving" class="spinner-border spinner-border-sm me-1"></span>
          {{ saving ? 'Guardando...' : 'Crear Entidad' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ══ MODAL: Editar Entidad ═════════════════════════════════════════════════ -->
<div class="modal fade" id="editModal" tabindex="-1">
  <div class="modal-dialog modal-lg">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-pencil-square me-2"></i>Editar Entidad</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="editForm">
          <div class="row g-3">
            <div class="col-12">
              <label class="form-label fw-semibold">Nombre <span class="text-danger">*</span></label>
              <input type="text" class="form-control" formControlName="nombre" />
              <div class="text-danger small mt-1"
                *ngIf="editForm.get('nombre')?.touched && editForm.get('nombre')?.invalid">
                Mínimo 3 caracteres
              </div>
            </div>

            <div class="col-md-6">
              <label class="form-label fw-semibold">Fecha de vencimiento de soporte</label>
              <input type="date" class="form-control" formControlName="fechaVencimientoSoporte" />
            </div>

            <div class="col-md-6 d-flex align-items-end">
              <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" formControlName="estado" id="editEstadoCheck" />
                <label class="form-check-label fw-semibold" for="editEstadoCheck">
                  Entidad activa (puede enviar solicitudes)
                </label>
              </div>
            </div>

            <div class="col-12">
              <label class="form-label fw-semibold">Correos de notificación</label>
              <div class="input-group mb-2">
                <input type="email" class="form-control"
                  [(ngModel)]="nuevoCorreoEdit" [ngModelOptions]="{standalone: true}"
                  placeholder="correo@ejemplo.com"
                  (keyup.enter)="agregarCorreoEdit()" />
                <button class="btn btn-outline-primary" type="button" (click)="agregarCorreoEdit()">
                  <i class="bi bi-plus-lg"></i> Agregar
                </button>
              </div>
              <div class="d-flex flex-wrap gap-2 mt-1">
                <span class="badge bg-primary d-flex align-items-center gap-1 py-2 px-2"
                  style="font-size:0.8rem"
                  *ngFor="let c of correosEdit; let i = index">
                  <i class="bi bi-envelope me-1"></i>{{ c }}
                  <button type="button" class="btn-close btn-close-white ms-1"
                    style="font-size:0.55rem" (click)="quitarCorreoEdit(i)"></button>
                </span>
                <span class="text-muted small fst-italic" *ngIf="!correosEdit.length">
                  Sin correos agregados
                </span>
              </div>
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarEdicion()" [disabled]="savingEdit">
          <span *ngIf="savingEdit" class="spinner-border spinner-border-sm me-1"></span>
          {{ savingEdit ? 'Guardando...' : 'Guardar Cambios' }}
        </button>
      </div>
    </div>
  </div>
</div>
